-- 0001_multi_practice_foundation.sql
-- Applied to Cloudflare D1: pra chi nutrition platform.
-- IDs are generated by the API; never trust practice_id or role supplied by the browser.
PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS practices (
 id TEXT PRIMARY KEY, name TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, owner_user_id TEXT,
 status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','active','suspended','closed')),
 timezone TEXT NOT NULL DEFAULT 'Asia/Kolkata', currency TEXT NOT NULL DEFAULT 'INR',
 created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')),
 updated_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE TABLE IF NOT EXISTS app_users (
 id TEXT PRIMARY KEY, email TEXT NOT NULL COLLATE NOCASE UNIQUE, display_name TEXT NOT NULL, phone TEXT,
 status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('invited','active','disabled','deleted')),
 created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')),
 updated_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE TABLE IF NOT EXISTS practice_memberships (
 id TEXT PRIMARY KEY, practice_id TEXT NOT NULL REFERENCES practices(id) ON DELETE CASCADE,
 user_id TEXT NOT NULL REFERENCES app_users(id) ON DELETE CASCADE,
 role TEXT NOT NULL CHECK(role IN ('owner','admin','dietitian','assistant','client')),
 status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('invited','active','suspended','removed')),
 created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')), UNIQUE(practice_id,user_id)
);
CREATE INDEX IF NOT EXISTS idx_memberships_user_status ON practice_memberships(user_id,status);
CREATE INDEX IF NOT EXISTS idx_memberships_practice_role ON practice_memberships(practice_id,role,status);
CREATE TABLE IF NOT EXISTS dietitian_profiles (
 id TEXT PRIMARY KEY, practice_id TEXT NOT NULL REFERENCES practices(id) ON DELETE CASCADE,
 user_id TEXT NOT NULL REFERENCES app_users(id) ON DELETE CASCADE, credentials TEXT, registration_number TEXT, bio TEXT,
 verification_status TEXT NOT NULL DEFAULT 'pending' CHECK(verification_status IN ('pending','verified','rejected','expired')),
 created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')), UNIQUE(practice_id,user_id)
);
CREATE INDEX IF NOT EXISTS idx_dietitians_practice_status ON dietitian_profiles(practice_id,verification_status);
CREATE TABLE IF NOT EXISTS client_profiles (
 id TEXT PRIMARY KEY, practice_id TEXT NOT NULL REFERENCES practices(id) ON DELETE CASCADE,
 user_id TEXT NOT NULL REFERENCES app_users(id) ON DELETE CASCADE,
 assigned_dietitian_user_id TEXT REFERENCES app_users(id) ON DELETE SET NULL,
 date_of_birth TEXT, preferred_name TEXT,
 onboarding_status TEXT NOT NULL DEFAULT 'incomplete' CHECK(onboarding_status IN ('incomplete','submitted','reviewed')),
 created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')), UNIQUE(practice_id,user_id)
);
CREATE INDEX IF NOT EXISTS idx_clients_practice_assigned ON client_profiles(practice_id,assigned_dietitian_user_id);
CREATE TABLE IF NOT EXISTS packages (
 id TEXT PRIMARY KEY, practice_id TEXT NOT NULL REFERENCES practices(id) ON DELETE CASCADE,
 name TEXT NOT NULL, description TEXT, price_minor INTEGER NOT NULL DEFAULT 0 CHECK(price_minor>=0),
 currency TEXT NOT NULL DEFAULT 'INR', duration_days INTEGER NOT NULL DEFAULT 30 CHECK(duration_days>0),
 features_json TEXT NOT NULL DEFAULT '[]', is_published INTEGER NOT NULL DEFAULT 0 CHECK(is_published IN (0,1)),
 created_by_user_id TEXT REFERENCES app_users(id) ON DELETE SET NULL,
 created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')),
 updated_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE INDEX IF NOT EXISTS idx_packages_practice_published ON packages(practice_id,is_published);
CREATE TABLE IF NOT EXISTS client_packages (
 id TEXT PRIMARY KEY, practice_id TEXT NOT NULL REFERENCES practices(id) ON DELETE CASCADE,
 client_user_id TEXT NOT NULL REFERENCES app_users(id) ON DELETE CASCADE,
 package_id TEXT NOT NULL REFERENCES packages(id) ON DELETE RESTRICT,
 assigned_dietitian_user_id TEXT REFERENCES app_users(id) ON DELETE SET NULL,
 status TEXT NOT NULL DEFAULT 'requested' CHECK(status IN ('requested','awaiting_payment','active','paused','completed','cancelled','refunded')),
 starts_at TEXT, ends_at TEXT,
 payment_status TEXT NOT NULL DEFAULT 'unpaid' CHECK(payment_status IN ('unpaid','pending','paid','failed','refunded','partially_refunded')),
 created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')),
 updated_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE INDEX IF NOT EXISTS idx_client_packages_client ON client_packages(practice_id,client_user_id,status);
CREATE INDEX IF NOT EXISTS idx_client_packages_dietitian ON client_packages(practice_id,assigned_dietitian_user_id,status);
CREATE TABLE IF NOT EXISTS diet_plans (
 id TEXT PRIMARY KEY, practice_id TEXT NOT NULL REFERENCES practices(id) ON DELETE CASCADE,
 client_user_id TEXT NOT NULL REFERENCES app_users(id) ON DELETE CASCADE,
 dietitian_user_id TEXT NOT NULL REFERENCES app_users(id) ON DELETE RESTRICT,
 title TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','archived')),
 current_version INTEGER NOT NULL DEFAULT 1,
 created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')),
 updated_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE INDEX IF NOT EXISTS idx_diet_plans_client_status ON diet_plans(practice_id,client_user_id,status);
CREATE INDEX IF NOT EXISTS idx_diet_plans_dietitian ON diet_plans(practice_id,dietitian_user_id,status);
CREATE TABLE IF NOT EXISTS diet_plan_versions (
 id TEXT PRIMARY KEY, plan_id TEXT NOT NULL REFERENCES diet_plans(id) ON DELETE CASCADE,
 version_number INTEGER NOT NULL, plan_json TEXT NOT NULL, notes TEXT, published_at TEXT,
 created_by_user_id TEXT NOT NULL REFERENCES app_users(id) ON DELETE RESTRICT,
 created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')), UNIQUE(plan_id,version_number)
);
CREATE TABLE IF NOT EXISTS conversations (
 id TEXT PRIMARY KEY, practice_id TEXT NOT NULL REFERENCES practices(id) ON DELETE CASCADE,
 client_user_id TEXT NOT NULL REFERENCES app_users(id) ON DELETE CASCADE,
 dietitian_user_id TEXT REFERENCES app_users(id) ON DELETE SET NULL,
 status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','closed','archived')),
 created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')),
 updated_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE INDEX IF NOT EXISTS idx_conversations_practice_client ON conversations(practice_id,client_user_id,status);
CREATE TABLE IF NOT EXISTS messages (
 id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,
 sender_user_id TEXT NOT NULL REFERENCES app_users(id) ON DELETE RESTRICT, body TEXT NOT NULL,
 attachment_metadata_json TEXT NOT NULL DEFAULT '[]', read_at TEXT,
 created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE INDEX IF NOT EXISTS idx_messages_conversation_created ON messages(conversation_id,created_at);
CREATE TABLE IF NOT EXISTS appointments (
 id TEXT PRIMARY KEY, practice_id TEXT NOT NULL REFERENCES practices(id) ON DELETE CASCADE,
 client_user_id TEXT NOT NULL REFERENCES app_users(id) ON DELETE CASCADE,
 dietitian_user_id TEXT REFERENCES app_users(id) ON DELETE SET NULL,
 starts_at TEXT NOT NULL, ends_at TEXT NOT NULL,
 status TEXT NOT NULL DEFAULT 'requested' CHECK(status IN ('requested','confirmed','completed','cancelled','no_show')),
 notes TEXT, created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')), CHECK(ends_at>starts_at)
);
CREATE INDEX IF NOT EXISTS idx_appointments_practice_dietitian_date ON appointments(practice_id,dietitian_user_id,starts_at,status);
CREATE INDEX IF NOT EXISTS idx_appointments_client_date ON appointments(practice_id,client_user_id,starts_at);
CREATE TABLE IF NOT EXISTS payment_orders (
 id TEXT PRIMARY KEY, practice_id TEXT NOT NULL REFERENCES practices(id) ON DELETE CASCADE,
 client_user_id TEXT NOT NULL REFERENCES app_users(id) ON DELETE RESTRICT,
 client_package_id TEXT REFERENCES client_packages(id) ON DELETE SET NULL,
 provider TEXT NOT NULL CHECK(provider IN ('razorpay','cashfree','manual','other')),
 provider_order_id TEXT, provider_payment_id TEXT, amount_minor INTEGER NOT NULL CHECK(amount_minor>=0),
 currency TEXT NOT NULL DEFAULT 'INR', status TEXT NOT NULL DEFAULT 'created' CHECK(status IN ('created','pending','paid','failed','cancelled','refunded')),
 idempotency_key TEXT NOT NULL UNIQUE, verified_at TEXT,
 created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')),
 updated_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE INDEX IF NOT EXISTS idx_payment_orders_practice_status ON payment_orders(practice_id,status,created_at);
CREATE TABLE IF NOT EXISTS audit_logs (
 id TEXT PRIMARY KEY, practice_id TEXT REFERENCES practices(id) ON DELETE SET NULL,
 actor_user_id TEXT REFERENCES app_users(id) ON DELETE SET NULL, action TEXT NOT NULL,
 resource_type TEXT NOT NULL, resource_id TEXT, metadata_json TEXT NOT NULL DEFAULT '{}',
 created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE INDEX IF NOT EXISTS idx_audit_practice_created ON audit_logs(practice_id,created_at);
